function main(): void {
let observedOrder = [];

function observableIterator() {
  let values = ["a", "b", "c"];
  let index = 0;
  return {
    get next() {
      observedOrder.push("getting next");
      return function () {
        observedOrder.push("calling next");
        return {
          get done() {
            observedOrder.push("getting done");
            return index >= values.length;
          },
          get value() {
            observedOrder.push("getting value");
            return values[index++];
          },
        };
      };
    },
  };
}

class MySetLike {
  get size() {
    observedOrder.push("getting size");
    return {
      valueOf: function () {
        observedOrder.push("ToNumber(size)");
        return 3;
      },
    };
  }
  get has() {
    observedOrder.push("getting has");
    return function (v) {
      throw new Test262Error("Set.prototype.isSupersetOf should not call its argument's has method");
    };
  }
  get keys() {
    observedOrder.push("getting keys");
    return function () {
      observedOrder.push("calling keys");
      return observableIterator();
    };
  }
}

// this is smaller than argument
{
  observedOrder = [];

  const s1 = new Set(["a", "b"]);
  const s2 = new MySetLike();
  const result = s1.isSupersetOf(s2);

  const expectedOrder = [
    "getting size",
    "ToNumber(size)",
    "getting has",
    "getting keys",
    // no iteration
  ];

  assert.sameValue(result, false);
  assert.compareArray(observedOrder, expectedOrder);
}

// this is same size as argument - stops eagerly
{
  observedOrder = [];

  const s1 = new Set(["a", "x", "c"]);
  const s2 = new MySetLike();
  const result = s1.isSupersetOf(s2);

  const expectedOrder = [
    "getting size",
    "ToNumber(size)",
    "getting has",
    "getting keys",
    "calling keys",
    "getting next",
    // first iteration, has value
    "calling next",
    "getting done",
    "getting value",
    // second iteration, has value
    "calling next",
    "getting done",
    "getting value",
  ];

  assert.sameValue(result, false);
  assert.compareArray(observedOrder, expectedOrder);
}

// this is same size as argument - full run
{
  observedOrder = [];

  const s1 = new Set(["a", "b", "c"]);
  const s2 = new MySetLike();
  const result = s1.isSupersetOf(s2);

  const expectedOrder = [
    "getting size",
    "ToNumber(size)",
    "getting has",
    "getting keys",
    "calling keys",
    "getting next",
    // first iteration, has value
    "calling next",
    "getting done",
    "getting value",
    // second iteration, has value
    "calling next",
    "getting done",
    "getting value",
    // third iteration, has value
    "calling next",
    "getting done",
    "getting value",
    // fourth iteration, no value; ends
    "calling next",
    "getting done",
  ];

  assert.sameValue(result, true);
  assert.compareArray(observedOrder, expectedOrder);
}

// this is larger than argument
{
  observedOrder = [];

  const s1 = new Set(["a", "b", "c", "d"]);
  const s2 = new MySetLike();
  const result = s1.isSupersetOf(s2);

  const expectedOrder = [
    "getting size",
    "ToNumber(size)",
    "getting has",
    "getting keys",
    "calling keys",
    "getting next",
    // first iteration, has value
    "calling next",
    "getting done",
    "getting value",
    // second iteration, has value
    "calling next",
    "getting done",
    "getting value",
    // third iteration, has value
    "calling next",
    "getting done",
    "getting value",
    // fourth iteration, no value; ends
    "calling next",
    "getting done",
  ];

  assert.sameValue(result, true);
  assert.compareArray(observedOrder, expectedOrder);
}
}
main();

function main(): void {
const iter = {
  a: [4, 5, 6],
  nextCalls: 0,
  returnCalls: 0,
  next() {
    const done = this.nextCalls >= this.a.length;
    const value = this.a[this.nextCalls];
    this.nextCalls++;
    return {done, value};
  },
  return() {
    this.returnCalls++;
    return this;
  },
};

const setlike = {
  size: iter.a.length,
  has(v) { return iter.a.includes(v); },
  keys() { return iter; },
};

// Set must be bigger than iter.a to hit iter.next and iter.return.
assert.sameValue(new Set([4, 5, 6, 7]).isSupersetOf(setlike), true);
assert.sameValue(iter.nextCalls, 4);
assert.sameValue(iter.returnCalls, 0);
iter.nextCalls = iter.returnCalls = 0;

assert.sameValue(new Set([0, 1, 2, 3]).isSupersetOf(setlike), false);
assert.sameValue(iter.nextCalls, 1);
assert.sameValue(iter.returnCalls, 1);
iter.nextCalls = iter.returnCalls = 0;
}
main();

